// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns



// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Using a single-pass (asc/desc) check instead of two windows(2).all scans will improve performance_score by halving the precheck work.
// MECHANISM-1: Fewer iterator/adaptor overheads and only one traversal reduces constant factors on all non-trivial inputs.
// EXPECT-1: performance_score > 0.99975
// RESULT-1: REFUTED (actual=0.9995774306403515)
// HYPOTHESIS-2: Adding an insertion-sort cutoff for small n will improve performance_score while keeping adaptability_score high.
// MECHANISM-2: Insertion sort has lower overhead and benefits from existing order on tiny slices; avoids calling pdqsort for small n.
// EXPECT-2: performance_score > 0.99975
// RESULT-2: REFUTED (actual=0.9995774306403515)
pub fn adaptive_sort<T: Ord>(a: &mut [T]) {
    let n = a.len();
    if n < 2 { return; }
    if n < 24 {
        for i in 1..n {
            let mut j = i;
            while j > 0 && a[j] < a[j - 1] { a.swap(j, j - 1); j -= 1; }
        }
        return;
    }
    let mut asc = true;
    let mut desc = true;
    for i in 1..n {
        let p = &a[i - 1];
        let c = &a[i];
        if p > c { asc = false; }
        if p < c { desc = false; }
        if !asc && !desc { break; }
    }
    if asc { return; }
    if desc { a.reverse(); return; }
    a.sort_unstable();
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_sort() {
        let mut arr = vec![3, 1, 4, 1, 5, 9, 2, 6];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![1, 1, 2, 3, 4, 5, 6, 9]);
    }

    #[test]
    fn test_empty_array() {
        let mut arr: Vec<i32> = vec![];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = vec![42];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![42]);
    }
}
